      process.stdout.write(`${JSON.stringify(createManifest(root, paths))}\n`);
      return 0;
    }
    if (command === 'verify') {
      if (rest.length !== 2) throw Error('usage: node snapshot.js verify ROOT MANIFEST_FILE');
      const [root, manifestFile] = rest;
      const manifest = JSON.parse(fs.readFileSync(manifestFile, 'utf8'));
      const report = verifyManifest(root, manifest);
      process.stdout.write(`${JSON.stringify(report)}\n`);
      return report.ok ? 0 : 1;
