    throw Error('usage: node snapshot.js create ROOT [PATH ...] | node snapshot.js verify ROOT MANIFEST_FILE');
  } catch (error) {
    process.stderr.write(`${error instanceof Error && error.message ? error.message : String(error)}\n`);
    return 2;
  }
