import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import * as snapshot from '../snapshot.js';

const repoRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
const HEX64 = 'a'.repeat(64);

function fixture(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-verify-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  return dir;
}
function entry(p, data = 'abc', mode = 0o644, shaOverride) {
  return { path: p, sha256: shaOverride ?? sha(data), size: data.length, mode };
}
function deepFreeze(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return value;
}

test('verify reports unchanged for nested, spaced, and unicode names', t => {
  const root = fixture(t);
  fs.mkdirSync(path.join(root, 'a', 'b'), { recursive: true });
  const weird = 'ünïcode\tspaced\nname.txt';
  fs.writeFileSync(path.join(root, 'a', 'b', weird), 'abc');
  fs.writeFileSync(path.join(root, 'plain.txt'), 'xyzzy');
  const manifest = { version: 1, files: [entry('plain.txt', 'xyzzy'), entry(`a/b/${weird}`)] };
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: true,
    unchanged: [`a/b/${weird}`, 'plain.txt'],
    changed: [], missing: [], unsafe: [],
  });
});

test('verify distinguishes content, mode, and both reasons in order', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'same-size'), 'abc');
  fs.writeFileSync(path.join(root, 'longer'), 'abc');
  fs.writeFileSync(path.join(root, 'both'), 'abc');
  fs.writeFileSync(path.join(root, 'mode-only'), 'abc');
  fs.chmodSync(path.join(root, 'mode-only'), 0o600);
  fs.chmodSync(path.join(root, 'both'), 0o601);
  const manifest = { version: 1, files: [
    entry('same-size', 'abd'),
    entry('longer', 'abcdef'),
    entry('both', 'zzz', 0o644),
    entry('mode-only', 'abc', 0o644),
  ]};
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: false,
    unchanged: [],
    changed: [
      { path: 'both', reasons: ['content', 'mode'] },
      { path: 'longer', reasons: ['content'] },
      { path: 'mode-only', reasons: ['mode'] },
      { path: 'same-size', reasons: ['content'] },
    ],
    missing: [], unsafe: [],
  });
});

test('verify classifies missing and unsafe components without following symlinks', t => {
  const root = fixture(t);
  fs.mkdirSync(path.join(root, 'sub'), { recursive: true });
  fs.writeFileSync(path.join(root, 'sub', 'real.txt'), 'abc');
  fs.writeFileSync(path.join(root, 'a-file'), 'abc');
  fs.symlinkSync(path.join(root, 'sub', 'real.txt'), path.join(root, 'link-in.txt'));
  fs.symlinkSync(path.join(root, 'sub'), path.join(root, 'link-dir'));
  fs.symlinkSync(path.join(root, 'no-target'), path.join(root, 'dangling'));
  const manifest = { version: 1, files: [
    entry('gone.txt'),
    entry('gone/deep/file.txt'),
    entry('sub/gone.txt'),
    entry('link-in.txt'),
    entry('link-dir/real.txt'),
    entry('dangling'),
    entry('a-file/under-file'),
    entry('sub'),
    entry('sub/real.txt'),
  ]};
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: false,
    unchanged: ['sub/real.txt'],
    changed: [],
    missing: ['gone.txt', 'gone/deep/file.txt', 'sub/gone.txt'],
    unsafe: ['a-file/under-file', 'dangling', 'link-dir/real.txt', 'link-in.txt', 'sub'],
  });
});

test('verify sorts unsorted entries by JavaScript string order', t => {
  const root = fixture(t);
  for (const name of ['Zeta', 'alpha', 'B2', 'b10', 'b2']) {
    fs.writeFileSync(path.join(root, name), 'abc');
    fs.unlinkSync(path.join(root, name));
    fs.writeFileSync(path.join(root, name), 'changed');
  }
  const manifest = { version: 1, files: ['b2', 'b10', 'alpha', 'B2', 'Zeta'].map(p => entry(p, 'abc')) };
  assert.deepEqual(snapshot.verifyManifest(root, manifest).changed.map(c => c.path), ['B2', 'Zeta', 'alpha', 'b10', 'b2']);
});

test('verify accepts empty file list and ignores unknown fields', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  assert.deepEqual(snapshot.verifyManifest(root, { version: 1, files: [], extra: 1 }), {
    ok: true, unchanged: [], changed: [], missing: [], unsafe: [],
  });
  const manifest = { version: 1, note: 'x', files: [{ ...entry('a.txt'), extra: [1, 2] }] };
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [],
  });
});

test('verify does not mutate its inputs', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.writeFileSync(path.join(root, 'b.txt'), 'def');
  const manifest = deepFreeze({ version: 1, files: [entry('b.txt', 'def'), entry('a.txt')] });
  assert.deepEqual(snapshot.verifyManifest(root, manifest), {
    ok: true, unchanged: ['a.txt', 'b.txt'], changed: [], missing: [], unsafe: [],
  });
  const paths = deepFreeze(['b.txt', 'a.txt']);
  const built = snapshot.createManifest(root, paths);
  assert.deepEqual(built.files.map(f => f.path), ['a.txt', 'b.txt']);
});

test('verify rejects invalid manifests before touching the filesystem', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  const valid = () => ({ version: 1, files: [entry('a.txt')] });
  const badManifests = [
    null, 42, 'manifest', true, [valid()],
    { version: 2, files: [] }, { version: '1', files: [] }, { files: [] }, { version: 1 },
    { version: 1, files: 'nope' }, { version: 1, files: null },
    { version: 1, files: [null] }, { version: 1, files: [42] }, { version: 1, files: [['a']] },
    { version: 1, files: [entry('a.txt'), entry('a.txt')] },
    { version: 1, files: [{ ...entry('a.txt'), path: '' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: '/abs' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a/b\\c' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a\0b' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a/./b' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a/../b' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a//b' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 'a/' }] },
    { version: 1, files: [{ ...entry('a.txt'), path: 7 }] },
    { version: 1, files: [{ ...entry('a.txt'), sha256: HEX64.toUpperCase() }] },
    { version: 1, files: [{ ...entry('a.txt'), sha256: 'g'.repeat(64) }] },
    { version: 1, files: [{ ...entry('a.txt'), sha256: 'a'.repeat(63) }] },
    { version: 1, files: [{ ...entry('a.txt'), sha256: 1 }] },
    { version: 1, files: [{ ...entry('a.txt'), size: -1 }] },
    { version: 1, files: [{ ...entry('a.txt'), size: 1.5 }] },
    { version: 1, files: [{ ...entry('a.txt'), size: Number.MAX_SAFE_INTEGER + 1 }] },
    { version: 1, files: [{ ...entry('a.txt'), size: '3' }] },
    { version: 1, files: [{ ...entry('a.txt'), mode: 512 }] },
    { version: 1, files: [{ ...entry('a.txt'), mode: -1 }] },
    { version: 1, files: [{ ...entry('a.txt'), mode: 1.5 }] },
    { version: 1, files: [{ ...entry('a.txt'), mode: '644' }] },
  ];
  for (const bad of badManifests) assert.throws(() => snapshot.verifyManifest(root, bad), Error);
});

test('verify rejects invalid roots', t => {
  const root = fixture(t);
  const file = path.join(root, 'file');
  fs.writeFileSync(file, 'abc');
  const link = path.join(root, 'link');
  fs.symlinkSync(root, link);
  assert.throws(() => snapshot.verifyManifest(path.join(root, 'nope'), { version: 1, files: [] }), Error);
  assert.throws(() => snapshot.verifyManifest(file, { version: 1, files: [] }), Error);
  assert.throws(() => snapshot.verifyManifest(link, { version: 1, files: [] }), Error);
});

test('createManifest keeps original behavior and errors', t => {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  assert.deepEqual(snapshot.createManifest(root, []), { version: 1, files: [] });
  assert.throws(() => snapshot.createManifest(root, null), Error);
  assert.throws(() => snapshot.createManifest(root, ['a.txt', 'a.txt']), Error);
  assert.throws(() => snapshot.createManifest(root, ['nope.txt']), Error);
  fs.mkdirSync(path.join(root, 'dir'));
  assert.throws(() => snapshot.createManifest(root, ['dir']), Error);
});

function runCli(args) {
  return spawnSync(process.execPath, [path.join(repoRoot, 'snapshot.js'), ...args], { encoding: 'utf8' });
}
function cliFixture(t) {
  const root = fixture(t);
  fs.writeFileSync(path.join(root, 'a.txt'), 'abc');
  fs.chmodSync(path.join(root, 'a.txt'), 0o640);
  return root;
}

test('cli create prints the manifest and exits 0', t => {
  const root = cliFixture(t);
  const expected = snapshot.createManifest(root, ['a.txt']);
  const result = runCli(['create', root, 'a.txt']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, `${JSON.stringify(expected)}\n`);
  assert.equal(result.stderr, '');
  const empty = runCli(['create', root]);
  assert.equal(empty.status, 0);
  assert.equal(empty.stdout, `${JSON.stringify({ version: 1, files: [] })}\n`);
  assert.equal(empty.stderr, '');
});

test('cli verify exits 0 for ok and 1 for drift with clean streams', t => {
  const root = cliFixture(t);
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, JSON.stringify(snapshot.createManifest(root, ['a.txt'])));
  const okRun = runCli(['verify', root, manifestFile]);
  assert.equal(okRun.status, 0);
  assert.deepEqual(JSON.parse(okRun.stdout), { ok: true, unchanged: ['a.txt'], changed: [], missing: [], unsafe: [] });
  assert.equal(okRun.stdout.endsWith('\n'), true);
  assert.equal(okRun.stderr, '');
  fs.writeFileSync(path.join(root, 'a.txt'), 'different!');
  const driftRun = runCli(['verify', root, manifestFile]);
  assert.equal(driftRun.status, 1);
  assert.deepEqual(JSON.parse(driftRun.stdout), {
    ok: false, unchanged: [], changed: [{ path: 'a.txt', reasons: ['content'] }], missing: [], unsafe: [],
  });
  assert.equal(driftRun.stderr, '');
});

test('cli exits 2 with stderr and no stdout on any error', t => {
  const root = cliFixture(t);
  const cases = [
    [],
    ['bogus', root],
    ['create'],
    ['create', path.join(root, 'absent-root')],
    ['create', root, '../outside'],
    ['verify', root],
    ['verify', root, path.join(root, 'absent-manifest.json')],
    ['verify', path.join(root, 'absent-root'), path.join(root, 'm.json')],
  ];
  for (const args of cases) {
    const result = runCli(args);
    assert.equal(result.status, 2, JSON.stringify(args));
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0, JSON.stringify(args));
  }
  const badJson = path.join(root, 'bad.json');
  fs.writeFileSync(badJson, '{not json');
  let result = runCli(['verify', root, badJson]);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.ok(result.stderr.length > 0);
  const badManifest = path.join(root, 'bad-manifest.json');
  fs.writeFileSync(badManifest, JSON.stringify({ version: 2, files: [] }));
  result = runCli(['verify', root, badManifest]);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.ok(result.stderr.length > 0);
  fs.writeFileSync(badManifest, JSON.stringify({ version: 1, files: [entry('a.txt', 'abc', 0o640)] }));
  const extra = runCli(['verify', root, badManifest, 'surplus']);
  assert.equal(extra.status, 2);
  assert.equal(extra.stdout, '');
  assert.ok(extra.stderr.length > 0);
});

test('importing the module does not run the CLI', () => {
  assert.equal(typeof snapshot.createManifest, 'function');
  assert.equal(typeof snapshot.verifyManifest, 'function');
});

